  async function loadCloudData(user){if(!user||!cloudDb)return;try{const snap=await cloudDb.collection('users').doc(user.uid).get();if(snap.exists){const data=snap.data();profile={name:data.name||user.displayName||'',email:user.email||data.email||''};garageVehicle=data.garageVehicle||garageVehicle;save('gtshop_profile',profile);save('gtshop_garage_vehicle',garageVehicle);}else{profile={name:user.displayName||'',email:user.email||''};await saveCloudData();}if(['/profile','/garage'].includes(getRoute().path))render();}catch(err){console.error('Firestore profile load failed',err);showToast('Не удалось загрузить профиль из базы');}}
